python - <<'PY'
import pandas as pd,re
D=pd.read_csv('b3_supercon_data.csv')
allowed={'O','Cu','Ba','Sr','Y','Ca','La','Bi','Fe','Nb','C','Pr','As','B','Pb','Ce','Mo','V','Zn','Ni'}
def parse(s):
 d={}
 for e,v in re.findall(r'([A-Z][a-z]?)([0-9.]*)',s):
  d[e]=d.get(e,0)+float(v or 1)
 sm=sum(d.values())
 return {e:v/sm for e,v in d.items()}
D['p']=D.composition.map(parse)
D['nels']=D.p.map(len)
D['allowed_only']=D.p.map(lambda d:set(d)<=allowed)
for _,r in D[(D.allowed_only)&(D.nels<=4)].sort_values('target',ascending=False).head(35).iterrows(): print(r.composition,r.target,r.p)
print('\nTop all')
for _,r in D.sort_values('target',ascending=False).head(25).iterrows(): print(r.composition,r.target,r.p)
